	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.serviceProviderSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for ServiceProvider : " + successValue.getServiceProviderId());
							  if (successValue.getServiceProviderId().equals(serviceProviderId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfServiceProviderList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("ServiceProvider test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on serviceProvider consumed")
					);
			subscriber.serviceProviderSubscribe( serviceProviderId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for ServiceProvider : " + successValue.getServiceProviderId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfServiceProviderList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on serviceProvider for serviceProviderId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a ServiceProvider. 
	 */
	protected ServiceProvider read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created ServiceProvider" );

		ServiceProvider entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read ServiceProvider with primary key" );
		msg.append( serviceProviderId );
		
		ServiceProviderFetchOneSummary fetchOneSummary = new ServiceProviderFetchOneSummary( serviceProviderId );

		try {
			entity = ServiceProviderService.getServiceProviderInstance().getServiceProvider( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found ServiceProvider " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a ServiceProvider.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a ServiceProvider." );

		StringBuilder msg = new StringBuilder( "Failed to update a ServiceProvider : " );        
		ServiceProvider entity = read();
		UpdateServiceProviderCommand command = generateUpdateCommand();
		command.setServiceProviderId(entity.getServiceProviderId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created ServiceProvider." );

			// for use later on...
			serviceProviderId = entity.getServiceProviderId();

			ServiceProviderService proxy = ServiceProviderService.getServiceProviderInstance();  

			proxy.updateServiceProvider( command ).get();

			LOGGER.info( "-- Successfully saved ServiceProvider - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + serviceProviderId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a ServiceProvider.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created ServiceProvider." );

		ServiceProvider entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read ServiceProvider with id " + serviceProviderId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read ServiceProvider with id " + serviceProviderId );

			throw e;
		}

		try{
			ServiceProviderService.getServiceProviderInstance().delete( new DeleteServiceProviderCommand( entity.getServiceProviderId() ) ).get();
			LOGGER.info( "-- Successfully deleted ServiceProvider with id " + serviceProviderId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete ServiceProvider with id " + serviceProviderId );

			throw e;
		}
	}

	/**
	 * get all ServiceProviders.
	 */
	protected List<ServiceProvider> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of ServiceProviders:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all ServiceProvider : " );        
		List<ServiceProvider> collection  = new ArrayList<>();

		try {
			// call the static get method on the ServiceProviderService
			collection = ServiceProviderService.getServiceProviderInstance().getAllServiceProvider();
			assertNotNull( collection, "An Empty collection of ServiceProvider was incorrectly returned.");
			
			// Now print out the values
			ServiceProvider entity = null;            
			Iterator<ServiceProvider> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getServiceProviderId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

